#include <iostream>
#include <algorithm>
#include <string>
using namespace std;

using i128 = __int128_t;

void printInt128(i128 value) {
    if (value == 0) {
        cout << 0;
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    cout << result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x, y, z;
    cin >> x >> y >> z;

    i128 a = x, b = y, c = z;

    if (max(a, b) >= c) {
        cout << 0;
        return 0;
    }

    if (a <= 0 && b <= 0) {
        cout << -1;
        return 0;
    }

    if (a > b)
        swap(a, b);

    i128 ans = 0;

    if (a < 0) {
        i128 steps = (-a + b - 1) / b;
        a += steps * b;
        ans += steps;
    }

    while (a < c && b < c) {
        a += b;
        ++ans;
        if (a > b)
            swap(a, b);
    }

    printInt128(ans);
    return 0;
}

